cypress_script:
describe('JavaScript Alert Dialogs Tests', () => {
  it('should show JS alert and dismiss it', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Alert').click();
    cy.on('window:alert', (text) => {
      expect(text).to.eq('I am a JS Alert');
    });
    cy.get('#result').should('be.visible');
  });

  it('should show JS prompt and return input', () => {
    cy.visit('https://the-internet.herokuapp.com/javascript_alerts');
    cy.contains('button', 'Click for JS Prompt').click();
    cy.window().then((win) => {
      cy.stub(win, 'prompt').returns('Cypress Test');
    });
    cy.get('#result').should('be.visible').contains('Cypress Test');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('JavaScript Alert Dialogs Tests', () => {
  test('should show JS alert and dismiss it', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    await page.click('button:has-text("Click for JS Alert")');
    page.on('dialog', async dialog => {
      expect(dialog.message()).toBe('I am a JS Alert');
      await dialog.dismiss();
    });
    await expect(page.locator('#result')).toBeVisible();
  });

  test('should show JS prompt and return input', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
    await page.click('button:has-text("Click for JS Prompt")');
    page.on('dialog', async dialog => {
      await dialog.accept('Playwright Test');
    });
    await expect(page.locator('#result')).toHaveText('Playwright Test');
  });
});
